insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-st-105', 'chemistry-stoichiometry', 'chemistry', 'Avogadro’s hypothesis, used with Gay-Lussac’s volume data, states that equal volumes of gases at the same T and P contain', '["equal numbers of molecules","equal masses of gas","equal numbers of atoms in every case","one mole only if the gas is monatomic"]'::jsonb, 0, 'Equal gas volumes at the same T and P hold the same number of molecules, which explains simple volume ratios.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'laws-combination') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
